/**
 * jsonmedic — Core Repair Engine (the engine behind https://aijsonmedic.com)
 *
 * Orchestrates a sequential repair pipeline optimised for JSON generated by
 * AI language models (ChatGPT, Claude, Gemini, DeepSeek, LLM APIs, n8n AI
 * nodes, LangChain, LlamaIndex, etc.).
 *
 * Pipeline stages (in order — ordering matters):
 *
 *  1. Pre-validate  — return immediately if input is already valid JSON
 *  2. Encoding      — strip BOM, null bytes, Unicode space variants
 *  3. Markdown      — extract JSON from ```json ... ``` and similar wrappers
 *  4. Comments      — strip // line comments, block comments, # hash
 *  5. Python        — True/False/None → true/false/null
 *  4.5 Concatenated — several top-level values / NDJSON → one array
 *  6. Values        — NaN/Infinity/undefined → null
 *  6.5 Numbers      — hex, leading +, malformed decimals → JSON numbers
 *  7. Quotes        — single-quoted strings → double-quoted
 *  8. Keys          — unquoted object keys → quoted
 *  9. Trailing ','  — remove trailing commas before ] or }
 * 10. Missing ','   — insert commas between adjacent values
 * 11. Truncation    — close unclosed strings and bracket structures
 * 11.5 Escapes      — double stray backslashes (Windows paths, regexes)
 * 12. Post-validate — attempt JSON.parse on repaired string
 * 12.5 Fallback     — the jsonrepair library, for what is still invalid
 * 13. Formatting    — beautify or minify the validated output
 * 14. Duplicates    — detect duplicate keys (warning, no auto-fix)
 */

import type { RepairIssue, RepairOptions, RepairResult } from './types';
import { DEFAULT_OPTIONS } from './types';
import { fixEncoding } from './encoding';
import { stripMarkdownFences } from './markdown';
import { stripComments } from './comments';
import { fixPythonLiterals } from './python';
import { fixInvalidValues } from './values';
import { fixInvalidEscapes } from './escapes';
import { fixNumbers } from './numbers';
import { mergeConcatenated } from './concat';
import { fixSingleQuotes, fixUnquotedKeys } from './quotes';
import { fixTrailingCommas, fixMissingCommas } from './commas';
import { repairTruncation } from './truncation';
import { detectDuplicateKeys } from './duplicates';
import { jsonrepair } from 'jsonrepair';
import { formatJsonLossless } from './format';

export type { RepairResult, RepairIssue, RepairOptions } from './types';

// ─── Public API ──────────────────────────────────────────────────────────────

/**
 * Main entry point. Takes any string (possibly broken AI JSON output)
 * and returns a fully structured repair result.
 *
 * @example
 * ```ts
 * import { repairJson } from 'jsonmedic';
 *
 * const result = repairJson("```json\n{\"ok\": True,}\n```");
 * // result.output  → '{\n  "ok": true\n}'
 * // result.issues  → [markdown fix, python fix, trailing-comma fix]
 * ```
 */
export function repairJson(
  input: string,
  options?: RepairOptions,
): RepairResult {
  const t0 = performance.now();
  const opts = { ...DEFAULT_OPTIONS, ...options };
  const allIssues: RepairIssue[] = [];
  const unfixable: RepairIssue[] = [];

  if (typeof input !== 'string') {
    return buildResult({
      output: '',
      isValid: false,
      wasAlreadyValid: false,
      issues: [],
      unfixable: [
        {
          category: 'structural',
          severity: 'unfixable',
          description: 'Input is not a string',
          line: null,
          col: null,
          before: String(typeof input),
          after: null,
        },
      ],
      durationMs: elapsed(t0),
    });
  }

  // ── Stage 0: Fast-path for empty input ──────────────────────────────────
  if (!input.trim()) {
    return buildResult({
      output: '',
      isValid: false,
      wasAlreadyValid: false,
      issues: [],
      unfixable: [
        {
          category: 'structural',
          severity: 'unfixable',
          description: 'Input is empty',
          line: null,
          col: null,
          before: '',
          after: null,
        },
      ],
      durationMs: elapsed(t0),
    });
  }

  // ── Stage 1: Pre-validate — skip repair if already valid ─────────────────
  // (unless it holds a raw Windows path: "C:\temp" parses, as C:<tab>emp — the escapes stage below fixes that)
  if (isValidJson(input) && !(opts.fixEscapes && hasWindowsPathHint(input))) {
    const formatted = opts.beautify
      ? formatJsonLossless(input, opts.indent)
      : (opts.beautify === false ? formatJsonLossless(input, 0) : input);
    const earlyIssues: RepairIssue[] = [];
    if (opts.warnDuplicateKeys) {
      // Run on original input — JSON.parse strips duplicates before stringify
      earlyIssues.push(...detectDuplicateKeys(input).issues);
    }
    return buildResult({
      output: formatted,
      isValid: true,
      wasAlreadyValid: true,
      issues: earlyIssues,
      unfixable: [],
      durationMs: elapsed(t0),
    });
  }

  // ── Stage 2: Encoding ────────────────────────────────────────────────────
  let s = input;
  {
    const r = fixEncoding(s);
    s = r.result;
    allIssues.push(...r.issues);
  }

  // ── Stage 3: Markdown ────────────────────────────────────────────────────
  if (opts.stripMarkdown) {
    const r = stripMarkdownFences(s);
    if (r) {
      s = r.result;
      allIssues.push(r.issue);
    }
  }

  // After stripping markdown, trim surrounding whitespace
  s = s.trim();

  // ── Stage 4: Comments ────────────────────────────────────────────────────
  if (opts.stripComments) {
    const r = stripComments(s);
    s = r.result;
    allIssues.push(...r.issues);
  }

  // ── Stage 4.5: Concatenated / NDJSON values → single array ───────────────
  if (opts.mergeConcatenated) {
    const r = mergeConcatenated(s);
    s = r.result;
    allIssues.push(...r.issues);
  }

  // ── Stage 5: Python literals ─────────────────────────────────────────────
  if (opts.fixPythonLiterals) {
    const r = fixPythonLiterals(s);
    s = r.result;
    allIssues.push(...r.issues);
  }

  // ── Stage 6: Invalid values ──────────────────────────────────────────────
  if (opts.replaceInvalidValues) {
    const r = fixInvalidValues(s);
    s = r.result;
    allIssues.push(...r.issues);
  }

  // ── Stage 6.5: Number normalization ──────────────────────────────────────
  if (opts.normalizeNumbers) {
    const r = fixNumbers(s);
    s = r.result;
    allIssues.push(...r.issues);
  }

  // ── Stage 7: Quote style ─────────────────────────────────────────────────
  if (opts.fixQuotes) {
    const r = fixSingleQuotes(s);
    s = r.result;
    allIssues.push(...r.issues);
  }

  // ── Stage 8: Unquoted keys ───────────────────────────────────────────────
  if (opts.fixUnquotedKeys) {
    const r = fixUnquotedKeys(s);
    s = r.result;
    allIssues.push(...r.issues);
  }

  // ── Stage 9: Trailing commas ─────────────────────────────────────────────
  if (opts.fixTrailingCommas) {
    const r = fixTrailingCommas(s);
    s = r.result;
    allIssues.push(...r.issues);
  }

  // ── Stage 10: Missing commas ─────────────────────────────────────────────
  if (opts.fixMissingCommas) {
    // Only run if we still have JSON-like content that isn't yet parseable
    if (!isValidJson(s)) {
      const r = fixMissingCommas(s);
      s = r.result;
      allIssues.push(...r.issues);
    }
  }

  // ── Stage 11: Truncation ─────────────────────────────────────────────────
  if (opts.repairTruncation) {
    if (!isValidJson(s)) {
      const r = repairTruncation(s);
      s = r.result;
      allIssues.push(...r.issues);
    }
  }

  // ── Stage 11.5: Invalid escapes ──────────────────────────────────────────
  // Before the fallback: jsonrepair drops an unknown escape's backslash (C:\Users → C:Users) and says nothing.
  if (opts.fixEscapes && (!isValidJson(s) || hasWindowsPathHint(s))) {
    const r = fixInvalidEscapes(s);
    if (r.issues.length) { s = r.result; allIssues.push(...r.issues); }
  }

  // ── Stage 12: Post-validate ──────────────────────────────────────────────
  let valid = isValidJson(s);

  // ── Stage 12.5: Fallback repair (jsonrepair) ─────────────────────────────
  // Last-resort safety net: if our explainable pipeline still couldn't produce
  // valid JSON, hand the input to the jsonrepair library so the long tail of
  // malformed input is still recovered (without a per-change explanation).
  if (!valid && opts.useFallback) {
    for (const candidate of [s, input]) {
      try {
        const repaired = jsonrepair(candidate);
        // English prose is never JSON: jsonrepair would make every word an array element (["Sure!", "Here", …])
        if (/^[A-Za-z]/.test(candidate.trimStart()) && repaired.trimStart().startsWith('[')) continue;
        if (isValidJson(repaired)) {
          s = repaired;
          valid = true;
          allIssues.push({
            category: 'structural',
            severity: 'fixed',
            description: 'Applied fallback structural repair for remaining errors',
            line: null,
            col: null,
            before: null,
            after: null,
          });
          break;
        }
      } catch { /* jsonrepair could not fix this candidate either */ }
    }
  }

  if (!valid) {
    // Collect any remaining parse error for the unfixable list
    const parseError = getParseError(s);
    if (parseError) {
      unfixable.push({
        category: 'structural',
        severity: 'unfixable',
        description: `Could not fully repair: ${parseError.message}`,
        line: parseError.line,
        col: parseError.col,
        before: null,
        after: null,
      });
    }
  }

  // ── Stage 13: Formatting ─────────────────────────────────────────────────
  let output: string;
  if (valid) {
    output = formatJsonLossless(s, opts.beautify ? opts.indent : 0);
  } else {
    // Even if not fully valid, return our best effort with original whitespace
    output = s;
  }

  // ── Stage 14: Duplicate key detection ────────────────────────────────────
  if (opts.warnDuplicateKeys && valid) {
    const r = detectDuplicateKeys(output);
    // Duplicates are warnings — they go into issues, not unfixable
    allIssues.push(...r.issues);
  }

  // Filter out issues that produced no actual change (no-ops)
  const meaningfulIssues = allIssues.filter(
    // a no-op is a snippet that did not change; a descriptive issue (no snippet, e.g. the fallback) always counts
    (issue) => issue.severity !== 'fixed' || issue.before !== issue.after || (issue.before === null && issue.after === null),
  );

  return buildResult({
    output,
    isValid: valid,
    wasAlreadyValid: false,
    issues: meaningfulIssues,
    unfixable,
    durationMs: elapsed(t0),
  });
}

// ─── Convenience wrappers ────────────────────────────────────────────────────

/** Returns true if the string is already valid JSON. */
export function isValidJson(input: string): boolean {
  try {
    JSON.parse(input);
    return true;
  } catch {
    return false;
  }
}

/**
 * Pretty-prints a valid JSON string. Lossless: numbers and strings are copied as written (no round trip through JS
 * doubles, which changed 1849203948571234567 → …4600 and 1e400 → null). Invalid input is returned unchanged.
 */
export function beautify(input: string, indent = 2): string {
  if (!isValidJson(input)) return input;
  return formatJsonLossless(input, indent);
}

/** Minifies a valid JSON string to a single line, losslessly (see beautify). Invalid input is returned unchanged. */
export function minify(input: string): string {
  if (!isValidJson(input)) return input;
  return formatJsonLossless(input, 0);
}

// ─── Internal helpers ────────────────────────────────────────────────────────

/** A drive path, UNC path or a well-known Windows folder with a single (unescaped) backslash after it. */
function hasWindowsPathHint(s: string): boolean {
  return /"\s*[A-Za-z]:\\(?!\\)|"\\\\[A-Za-z0-9._$-]+\\(?!\\)|\\(?:Users|Program Files|Windows)\\(?!\\)/i.test(s);
}

interface BuildResultArgs {
  output: string;
  isValid: boolean;
  wasAlreadyValid: boolean;
  issues: RepairIssue[];
  unfixable: RepairIssue[];
  durationMs: number;
}

function buildResult(args: BuildResultArgs): RepairResult {
  return {
    ...args,
    changeCount: args.issues.filter((i) => i.severity === 'fixed').length,
  };
}

interface ParseError {
  message: string;
  line: number | null;
  col: number | null;
}

function getParseError(input: string): ParseError | null {
  try {
    JSON.parse(input);
    return null;
  } catch (e) {
    const msg = (e as Error).message;
    // Extract line/col from V8 SyntaxError messages:
    // "Unexpected token '}' at JSON position 42"
    // "Expected ',' or '}' after property value in JSON at line 4 column 3"
    const lineColMatch = msg.match(/line (\d+) column (\d+)/);
    if (lineColMatch) {
      return {
        message: msg,
        line: parseInt(lineColMatch[1], 10),
        col: parseInt(lineColMatch[2], 10),
      };
    }
    return { message: msg, line: null, col: null };
  }
}

function elapsed(t0: number): number {
  return Math.round((performance.now() - t0) * 100) / 100;
}
